# Builds the "spoken" form of each voice-over line (numbers spelled out, symbols removed, tashkeel on hard names).
# The game still looks lines up by their displayed text; only the audio is generated from the spoken form.
import json, re, sys
EG = dict(ones=['','واحد','اتنين','تلاتة','أربعة','خمسة','ستة','سبعة','تمانية','تسعة'],
          teens=['عشرة','حداشر','اتناشر','تلتاشر','أربعتاشر','خمستاشر','ستاشر','سبعتاشر','تمنتاشر','تسعتاشر'],
          tens=['','','عشرين','تلاتين','أربعين','خمسين','ستين','سبعين','تمانين','تسعين'],
          hund=['','مية','ميتين','تلتمية','ربعمية','خمسمية','ستمية','سبعمية','تمنمية','تسعمية'],
          th={1:'ألف',2:'ألفين',3:'تلات تلاف',4:'أربع تلاف',5:'خمس تلاف',6:'ست تلاف',7:'سبع تلاف',8:'تمن تلاف',9:'تسع تلاف',10:'عشر تلاف'})
SA = dict(ones=['','واحد','اثنين','ثلاثة','أربعة','خمسة','ستة','سبعة','ثمانية','تسعة'],
          teens=['عشرة','إحدعش','اثنعش','ثلطعش','أربعطعش','خمسطعش','ستطعش','سبعطعش','ثمنطعش','تسعطعش'],
          tens=['','','عشرين','ثلاثين','أربعين','خمسين','ستين','سبعين','ثمانين','تسعين'],
          hund=['','مية','ميتين','ثلاثمية','أربعمية','خمسمية','ستمية','سبعمية','ثمانمية','تسعمية'],
          th={1:'ألف',2:'ألفين',3:'ثلاثة آلاف',4:'أربعة آلاف',5:'خمسة آلاف',6:'ستة آلاف',7:'سبعة آلاف',8:'ثمانية آلاف',9:'تسعة آلاف',10:'عشرة آلاف'})
def below100(n, L):
    if n < 10: return L['ones'][n]
    if n < 20: return L['teens'][n - 10]
    o, t = n % 10, n // 10
    return (L['ones'][o] + ' و' + L['tens'][t]) if o else L['tens'][t]
def words(n, L):
    if n == 0: return 'صفر'
    parts = []
    th, rest = divmod(n, 1000)
    if th: parts.append(L['th'].get(th) or (below100(th, L) + ' ألف'))
    h, r = divmod(rest, 100)
    if h: parts.append(L['hund'][h])
    if r: parts.append(below100(r, L))
    return ' و'.join(parts)
NAMES_EG = {'خوفو': 'خُوفُو', 'خفرع': 'خَفْرَع', 'منكاورع': 'مَنْكَاوْرَع', 'حتشبسوت': 'حَتْشِبْسُوت', 'تحتمس': 'تَحُتْمُس', 'نارمر': 'نَارْمِر', 'منف': 'مَنْف', 'أمنحتب': 'أَمِنْحُتِب', 'ممنون': 'مِمْنُون', 'نفرتاري': 'نِفِرْتَارِي', 'عنخ إسن آمون': 'عَنْخ إِسِن آمُون', 'توت عنخ آمون': 'تُوت عَنْخ آمُون', 'أنوبيس': 'أَنُوبِيس', 'الكانوبية': 'الكَانُوبِيَّة', 'شامبليون': 'شَامْبِلْيُون', 'البطلمي': 'البَطْلَمِي', 'كليوباترا': 'كِلْيُوبَاتْرَا', 'الكرنك': 'الكَرْنَك', 'الكباش': 'الكِبَاش', 'طيبة': 'طِيبَة', 'فيلة': 'فِيلَة', 'إيزيس': 'إِيزِيس', 'الفلوكة': 'الفَلُوكَة', 'الفلايك': 'الفَلَايِك', 'سمبل': 'سِمْبِل', 'البلو هول': 'البْلُو هُول', 'الغردقة': 'الغَرْدَقَة', 'نعمة': 'نِعْمَة', 'كاترين': 'كَاتْرِين', 'القروش': 'القُرُوش', 'إزاز': 'إِزَاز', 'طقطقة': 'طَقْطَقَة', 'سقّف': 'سَقَّف', 'البحري': 'البَحَرِي', 'الهيروغليفية': 'الهِيرُوغْلِيفِيَّة', 'بالهيروغليفي': 'بالهِيرُوغْلِيفِي', 'الهيروغليفي': 'الهِيرُوغْلِيفِي', 'التالت': 'التَّالِت', 'التاني': 'التَّانِي', 'التلاتة': 'التَّلَاتَة', 'رمسيس': 'رَمْسِيس', 'حورس': 'حُورَس', 'هوارد كارتر': 'هُوارْد كارْتَر', 'رشيد': 'رَشِيد', 'الأرز': 'الأَرْز', 'بيزوّقوا': 'بِيزَوَّقُوا', 'الفلوكه': 'الفَلُوكَة', 'دهب': 'دَهَب', 'الدهبي': 'الدَّهَبِي', 'بالدهب': 'بالدَّهَب', 'الدهب': 'الدَّهَب', 'بي تك': 'بِي تِك', 'دريم': 'دْرِيم', 'سبورت': 'سْبُورْت', 'سمارت': 'سْمَارْت', 'الكرواسون': 'الكْرُوَاسُون', 'كورنيه': 'كُورْنِيه', 'هايبر ماركت': 'هَايْبَر مَارْكِت', 'الأكواريوم': 'الأَكْوَارْيُوم', 'أكواريوم': 'أَكْوَارْيُوم', 'مارينا': 'مَارِينَا', 'تركواز': 'تُرْكْوَاز', 'كافيهات': 'كَافِيهَات', 'الغواصة': 'الغَوَّاصَة', 'الغواصين': 'الغَوَّاصِين', 'مطروح': 'مَطْرُوح', 'العلمين': 'العَلَمِين', 'البهو': 'البَهْو', 'منكاورع،': 'مَنْكَاوْرَع،', 'KV62': ''}
NAMES_SA = {'المصمك': 'المَصْمَك', 'الطريف': 'الطُّرَيْف', 'الدرعية': 'الدِّرْعِيَّة', 'الزل': 'الزِّل', 'الرواشين': 'الرَّوَاشِين', 'الروشان': 'الرُّوشَان', 'دادان': 'دَادَان', 'لحيان': 'لِحْيَان', 'الأنباط': 'الأَنْبَاط', 'ألمع': 'أَلْمَع', 'القط': 'القَطّ', 'عسير': 'عَسِير', 'العسيري': 'العَسِيرِي', 'السودة': 'السَّوْدَة', 'الديسة': 'الدِّيسَة', 'إثراء': 'إِثْرَاء', 'الظهران': 'الظَّهْرَان', 'الخبر': 'الخُبَر', 'الأحساء': 'الأَحْسَاء', 'البشوت': 'البُشُوت', 'عبدالعزيز': 'عبد العزيز', 'ﷺ': 'صلى الله عليه وسلم', 'العُلا': 'العُلَا', 'الحِجر': 'الحِجْر', 'مدائن صالح': 'مَدَائِن صَالِح', 'وش': 'وِشْ', 'تبي': 'تِبِي', 'حياك': 'حَيَّاك', 'الموية': 'المُويَة', 'موية': 'مُويَة', 'يسوون': 'يْسَوُّون', 'تلقى': 'تِلْقَى', 'اليونسكو': 'اليُونِسْكُو', 'جدة': 'جِدَّة', 'تبوك': 'تَبُوك', 'الدمام': 'الدَّمَّام', 'الربع الخالي': 'الرُّبْع الخَالِي', 'برج المملكة': 'بُرْج المَمْلَكَة'}
NAMES_AR = {'نزوى': 'نِزْوَى', 'شبام': 'شِبَام', 'زقورة': 'زَقُّورَة', 'أور': 'أُور', 'البتراء': 'البَتْرَاء', 'السيق': 'السِّيق', 'الأنباط': 'الأَنْبَاط', 'بعلبك': 'بَعْلَبَك', 'الأرز': 'الأَرْز', 'الجم': 'الجَمّ', 'لبدة': 'لَبْدَة', 'مروي': 'مَرَوِي', 'كوش': 'كُوش', 'شنقيط': 'شِنْقِيط', 'مقديشو': 'مُقَدِيشُو', 'ليدو': 'لِيدُو', 'عسل': 'عَسَل', 'كارتالا': 'كَارْتَالَا', 'باي': 'بَاي', 'آي إم': 'آي إِم', 'كلش': 'كِلِّش', 'بالطابوق': 'بالطَّابُوق', 'لفوك': 'لِفُوك', 'منو': 'مِنُو', 'عيوني': 'عْيُونِي', 'سومر': 'سُومَر', 'آشور': 'آشُور', 'الفانيلا': 'الفَانِيلَا', 'الدار البيضاء': 'الدَّار البَيْضَاء', 'الحسن': 'الحَسَن'}
def spoken(t, pack):
    L = SA if (pack == 'sa' or pack.startswith('ar_')) else EG
    s = t
    s = re.sub(r'[\U0001F000-\U0001FAFF☀-➿⬀-⯿️‍⃣]', '', s)
    s = s.replace('«', '').replace('»', '').replace(' — ', '، ').replace('—', '، ')
    s = re.sub(r'\s*\(([^)]*)\)', lambda m: ('' if re.fullmatch(r'[A-Z0-9]+', m.group(1)) else '، ' + m.group(1) + '،'), s)
    s = re.sub(r'(\d+)\s+لـ\s+(\d+)', r'\1 لحد \2', s)
    s = re.sub(r'(\d+)\.(\d)\s*كيلو', lambda m: f"{words(int(m.group(1)), L)} كيلو و{L['hund'][int(m.group(2))]} متر", s)
    s = re.sub(r'\d+', lambda m: words(int(m.group(0)), L), s)
    for k, v in sorted(({**NAMES_SA, **NAMES_AR} if pack.startswith('ar_') else NAMES_SA if pack == 'sa' else NAMES_EG).items(), key=lambda kv: -len(kv[0])):
        s = re.sub('(?<![\u0621-\u0652])([\u0648\u0628\u0644\u0641\u0643]?)' + re.escape(k) + '(?![\u0621-\u0652])', lambda m: m.group(1) + v, s)
    s = re.sub(r'،\s*،', '،', s); s = re.sub(r'،\s*\.', '.', s); s = re.sub(r'\s+([،.!؟?])', r'\1', s); s = re.sub(r'\s+', ' ', s).strip()
    return s
if __name__ == '__main__':
    for pack in sys.argv[1:]:
        lines = json.load(open(f'tools/vo-lines-{pack}.json'))
        out = {}
        for t in lines:
            clean = re.sub(r'\s+', ' ', re.sub(r'[\U0001F000-\U0001FAFF☀-➿⬀-⯿️‍⃣]', '', t)).strip()
            sp = spoken(t, pack)
            if sp != clean: out[clean] = sp
        json.dump(out, open(f'tools/vo-say-{pack}.json', 'w'), ensure_ascii=False, indent=0)
        print(pack, 'changed', len(out), 'of', len(lines), 'chars', sum(len(v) for v in out.values()))
